param([string]$Results='Temp/MillionScaleExecution/employment-checks',[string]$Save='',[string]$Reference='7047a7d',[switch]$RebuildOnly)
$ErrorActionPreference='Stop';$root=Split-Path $PSScriptRoot -Parent;. (Join-Path $PSScriptRoot 'ProjectLayout.ps1')
$out=Join-Path $root $Results;if(Test-Path -LiteralPath $out){throw 'Fresh output required'};New-Item -ItemType Directory -Path $out|Out-Null
$frozen=@{};foreach($relative in @('Core/CityEntities.cs','Residents/CityResidents.cs','Residents/CityJobs.cs','Industry/CityIndustry.cs','Economy/CityShopAccount.cs','Residents/CityCoreResidents.cs','Residents/CityHouseholds.cs','Core/CityCoreSave.cs','Industry/CityCoreIndustrySession.cs')){$name=[IO.Path]::GetFileName($relative);$path=Join-Path $out $name;$source=& git -C $root show ($Reference+':Assets/Scripts/Runtime/Simulation/'+$relative);if($LASTEXITCODE -ne 0){throw 'Frozen source unavailable'};[IO.File]::WriteAllLines($path,$source);$frozen[$name]=$path}
foreach($version in @('old','new')){$dir=Join-Path $out $version;New-Item -ItemType Directory -Path $dir|Out-Null;$overrides=@{};$defines='EMPLOYMENT_INDEX';if($version -eq 'old'){$overrides=$frozen;$defines=''};$binary=Build-CityDotNetHost -ProjectRoot $root -OutputDirectory $dir -Entry (New-CityOrderWitnessEntry $root (Join-Path $PSScriptRoot 'Diagnostics/CityEmploymentIndexChecks.cs') $dir) -Defines $defines -SourceOverrides $overrides;& dotnet $binary $dir;if($LASTEXITCODE -ne 0){throw ($version+' employment failed')}}
if([IO.File]::ReadAllText((Join-Path $out 'old/employment.csv')) -cne [IO.File]::ReadAllText((Join-Path $out 'new/employment.csv'))){throw 'Employment changed full city state'}
Write-Output ('PASS frozen '+$Reference+' vs employment index: exact city checkpoints and 1200-step warm/cold continuation')

if($Save){$originalSave=(Resolve-Path -LiteralPath $Save).Path;$orderSave=Export-CityMemberOrderFixture $root $originalSave $out;$runNumber=0;$finalHash=$null;foreach($version in @('old','new','new','old')){$run=Join-Path $out ('measure-'+$runNumber+'-'+$version);New-Item -ItemType Directory -Path $run|Out-Null;$Save=if($version -eq 'old'){$originalSave}else{$orderSave};$binary=Join-Path $out ($version+'/bin/Release/net10.0/CityModelHost.dll');if($RebuildOnly){& dotnet $binary $run (Resolve-Path -LiteralPath $Save).Path rebuild}else{& dotnet $binary $run (Resolve-Path -LiteralPath $Save).Path};if($LASTEXITCODE -ne 0){throw 'Maintenance measure failed'};[IO.File]::WriteAllText((Join-Path $run 'version.txt'),$version);$sample=Import-Csv (Join-Path $run $(if($RebuildOnly){'rebuild.csv'}else{'maintenance.csv'}));if($finalHash -and $sample.final_sha256 -cne $finalHash){throw 'Measured full city states differ'};$finalHash=$sample.final_sha256;$runNumber++}}
